import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for i in range(n):
        if me[i] == 'C':
            my_c += 1
        else:
            my_d += 1
        if op[i] == 'C':
            opp_c += 1
        else:
            opp_d += 1

    opp_rate = opp_c / n
    rounds_left = 100 - n

    # Endgame: extract the last few rounds when opponent is not fully cooperative.
    if rounds_left <= 2:
        if opp_rate > 0.95 and n > 5:
            return 'C'
        return 'D'

    if rounds_left <= 6:
        if opp_rate > 0.85:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'D'

    # Detect mostly unconditional cooperator: exploit, but keep some recovery room.
    if n >= 8 and opp_rate >= 0.92:
        if rounds_left > 20:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        return 'D'

    # Detect mostly unconditional defector: defect, with rare probes.
    if n >= 6 and opp_rate <= 0.12:
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Recent window for responsiveness.
    recent_len = min(10, n)
    recent_op = op[-recent_len:]
    recent_me = me[-recent_len:]
    recent_opp_c = 0
    recent_my_c = 0
    for i in range(recent_len):
        if recent_op[i] == 'C':
            recent_opp_c += 1
        if recent_me[i] == 'C':
            recent_my_c += 1
    recent_my_d = recent_len - recent_my_c

    last_op = op[-1]
    last_me = me[-1]

    # Opponent defection run detection.
    run_d = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        run_d += 1
        i -= 1

    # Mutual defection recovery: try to break a DD loop.
    if last_op == 'D' and last_me == 'D' and run_d >= 2:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Punish sustained defection, but signal willingness to return to cooperation.
    if run_d >= 3:
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # If opponent defected last round after mostly cooperating, treat as noise.
    if last_op == 'D':
        if opp_rate > 0.7 and recent_opp_c >= recent_len - 2:
            return 'C'
        if recent_opp_c >= recent_len - 1:
            return 'C'
        if opp_rate > 0.5 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round. Maintain mutual cooperation when stable.
    if recent_opp_c >= recent_len - 1 and recent_my_c >= recent_len - 1:
        return 'C'

    if opp_rate >= 0.75:
        if rng.random() < 0.03 and rounds_left > 15:
            return 'D'
        return 'C'

    # Mixed opponent: be forgiving but punish persistent exploitation.
    if recent_opp_c >= recent_len - 2:
        return 'C'

    if rng.random() < opp_rate:
        return 'C'
    return 'D'
